/*
 * A074911  Triangle generated by Pascal's rule, except begin and end the n-th
 *          row with n!.
 * https://oeis.org/A074911
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn, tabl
 * Formula:   not stated
 * Range:     u8 n <= 15, u16 n <= 36, u32 n <= 78, u64 n <= 210,
 *            u128 n <= 595, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * A074911:  Triangle generated by Pascal's rule,
 * except the first and last entry of an n‑th row is n!
 * The sequence a(n) is obtained by reading the triangle row‑by‑row.
 * The answer is returned for any n ≥ 1.
 *
 * Formula (informal):
 *   T(1,1) = 1,
 *   T(r,1) = T(r,r) = r!  (r ≥ 2)
 *   T(r,k) = T(r-1,k-1) + T(r-1,k)      (2 ≤ k ≤ r-1)
 *   a(n) = T(r,k) where r is the unique row with
 *          r(r-1)/2 + 1 ≤ n ≤ r(r+1)/2.
 *
 * The implementation builds the triangle on demand
 * up to the required row and caches all computed values.
 * It works for arbitrary precision seq_t as well
 * as for fixed width unsigned integer types.
 *
 * NOTE: Only +, -, *, /, and indexing are used on seq_t.
 */
#include <stdlib.h>  /* for malloc / realloc */

seq_t a(idx_t n) {
    /* a(0) is not defined in the OEIS entry – return 0 for safety. */
    if (n == 0) return 0;

    /* Find the row r that contains the index n.
       The cumulative count of elements up to row r is r(r+1)/2. */
    idx_t r = 1;
    while ((r * (r + 1)) / 2 < n) ++r;

    /* Static cache of the triangle values. */
    static seq_t *vals = NULL;      /* flattened array of all rows */
    static size_t vals_cap = 0;      /* allocated capacity of vals */
    static idx_t max_row = 0;          /* highest row that has been computed */
    static seq_t factorial = 1;          /* factorial of the current computed row */

    /* If we have not yet computed up to row r, extend the cache. */
    if (r > max_row) {
        /* Ensure enough space for all rows up to r. */
        size_t needed = (size_t)r * (r + 1) / 2;
        if (needed > vals_cap) {
            size_t new_cap = vals_cap ? vals_cap * 2 : 16;
            while (new_cap < needed) new_cap *= 2;
            vals = (seq_t *)realloc(vals, new_cap * sizeof(seq_t));
            vals_cap = new_cap;
        }

        /* Compute rows from max_row+1 up to r. */
        for (idx_t cur = max_row + 1; cur <= r; ++cur) {
            /* factorial of the current row */
            if (cur == 1)
                factorial = (seq_t)1;
            else
                factorial = factorial * (seq_t)cur;

            /* Start index (0‑based) of row cur in the flattened array. */
            idx_t start_cur = (cur - 1) * cur / 2;

            /* Fill first and last elements with factorial. */
            vals[start_cur] = factorial;
            if (cur > 1)
                vals[start_cur + cur - 1] = factorial;

            /* Compute interior elements using Pascal's rule. */
            if (cur > 2) {
                idx_t start_prev = (cur - 2) * (cur - 1) / 2;
                for (idx_t c = 1; c <= cur - 2; ++c)
                    vals[start_cur + c] =
                        vals[start_prev + (c - 1)] + vals[start_prev + c];
            }
        }
        max_row = r;
    }

    /* Determine the offset of n within row r (0‑based). */
    idx_t start_r1 = r * (r - 1) / 2 + 1;                 /* 1‑based start index of row r */
    idx_t offset   = n - start_r1;                       /* 0‑based offset in row */
    idx_t start0   = (r - 1) * r / 2;                    /* 0‑based start index in flattened array */

    return vals[start0 + offset];
}
